/** A workbook job — used for the detected-sheets assertions. */
export function workbookJob(overrides: Partial<ImportJobDetail> = {}): ImportJobDetail {
  const base = pendingJob();
  return {
    ...base,
    filename: 'sample_businesses.xlsx',
    file_type: 'xlsx',
    file_size: 20480,
    uploaded: {
      file_type: 'xlsx',
      file_size: 20480,
      sheets: ['Leads', 'Lookups'],
      sheet_count: 2,
      selected_sheet: 'Leads',
      encoding: '',
      delimiter: '',
      row_count: 8,
    },
    total_rows: 8,
    progress: { processed: 0, total: 8, percent: 0, is_active: true, awaiting_review: true },
    preview: { ...previewFixture, counts: { ...previewFixture.counts, total_rows: 8, rows_with_email: 7, rows_without_email: 1 } },
    ...overrides,
  };
}

